import { sys } from 'cc';
import type { BundleVersionInfo } from './BundleVersionInfo';
import { HOT_UPDATE_ENABLED_BUNDLES } from './HotUpdateConfig';
import type { HotUpdateView } from './HotUpdateView';

// 大廳透過 globalThis.__subGameData__ 傳進來的資料
interface SubGameData {
    cdnBase: string;
    gameId: string;
    /** 本次 session 實際載入的版本 來源不明時可能沒有 */
    version?: string;
    /** 本次 session 實際載入的 Bundle URL 來源不明時可能沒有 */
    packageUrl?: string;
}

// Web 只負責確認目前載入的 Bundle 是否仍和 CDN 最新發布一致
// 真正選擇與載入 Remote Bundle 已經由 entry 的 SubGame 負責
export async function checkWebBundleVersion(bundleName: string, ui?: HotUpdateView): Promise<void> {
    if (sys.isNative) {
        console.info('[WebBundleVersionCheck] 原生平台由 NativeBundleUpdater 處理 略過 Web 版本檢查');
        return;
    }

    if (!HOT_UPDATE_ENABLED_BUNDLES.has(bundleName)) {
        console.info(`[WebBundleVersionCheck] ${bundleName} 不在熱更白名單內 略過`);
        return;
    }

    // __subGameData__ 存在代表從 entry 大廳載入
    // 沒有就是 slot_game 獨立 Editor Preview
    const subGameData = (globalThis as any).__subGameData__ as SubGameData | undefined;

    console.info('[WebBundleVersionCheck] 收到大廳資料 __subGameData__=', JSON.stringify(subGameData ?? null));

    if (!subGameData?.cdnBase) {
        console.info('[WebBundleVersionCheck] 沒有大廳傳入的 cdnBase 略過版本檢查');
        return;
    }

    if (subGameData.gameId !== bundleName) {
        console.warn(`[WebBundleVersionCheck] gameId 不符 大廳=${subGameData.gameId} 目前=${bundleName} 略過`);
        return;
    }

    const cdnBase = subGameData.cdnBase.replace(/\/+$/, '');
    const versionUrl = `${cdnBase}/remote/${bundleName}/version.json`;

    ui?.show();
    ui?.setStatus('檢查版本中...');
    ui?.setProgress(0.1);

    console.info(`[WebBundleVersionCheck] 開始檢查 bundle=${bundleName}`);
    console.info(`[WebBundleVersionCheck] 查詢 ${versionUrl}`);

    try {
        const response = await fetch(`${versionUrl}?t=${Date.now()}`, {
            cache: 'no-store'
        });

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }

        const remote = (await response.json()) as BundleVersionInfo;

        ui?.setProgress(0.5);

        validateRemoteVersion(bundleName, remote);

        const remotePackageUrl = normalizeUrl(remote.packageUrl);
        const loadedPackageUrl = subGameData.packageUrl ? normalizeUrl(subGameData.packageUrl) : undefined;

        console.info(`[WebBundleVersionCheck] 遠端最新 v${remote.version} ${remotePackageUrl}`);

        if (!loadedPackageUrl) {
            // AssetManager 中原本就有同名 Bundle 時 Entry 不一定知道它的來源
            // 這種情況不能假裝知道目前載入的是哪個版本
            console.warn('[WebBundleVersionCheck] 目前 Bundle 來源不明 無法和遠端 packageUrl 比對');

            ui?.setStatus('版本檢查完成');
            ui?.setProgress(1);
            return;
        }

        ui?.setProgress(0.8);

        if (loadedPackageUrl === remotePackageUrl) {
            console.info(`[WebBundleVersionCheck] 版本一致 v${remote.version}`);

            ui?.setStatus(`版本 v${remote.version} 已是最新`);
            ui?.setProgress(1);
            return;
        }

        // Web 的最新 Bundle 已經由 Entry 進場前決定
        // 這裡出現不一致通常代表 CDN 在載入途中剛發布新版，
        // 或本 session 已經載入過舊版同名 Bundle。
        // 不在這裡 remove/reload，避免 script 重複註冊造成 duplicate CID。
        console.warn('[WebBundleVersionCheck] 目前載入版本與 CDN 最新版本不一致');
        console.warn(
            `[WebBundleVersionCheck]   目前: ${subGameData.version ? `v${subGameData.version} ` : ''}${loadedPackageUrl}`
        );
        console.warn(`[WebBundleVersionCheck]   最新: v${remote.version} ${remotePackageUrl}`);
        console.warn('[WebBundleVersionCheck] Web 本次 session 繼續使用目前已載入的 Bundle');

        ui?.setStatus('版本檢查完成');
        ui?.setProgress(1);
    } catch (err) {
        console.warn('[WebBundleVersionCheck] 版本檢查失敗 使用目前已載入版本繼續', err);

        ui?.setStatus('版本檢查失敗 使用目前版本');
        ui?.setProgress(1);
    }
}

function validateRemoteVersion(bundleName: string, remote: BundleVersionInfo): void {
    if (remote.bundleName !== bundleName) {
        throw new Error(`bundleName 不符 遠端=${remote.bundleName} 預期=${bundleName}`);
    }

    if (!/^\d+(?:\.\d+)*$/.test(remote.version)) {
        throw new Error(`version 格式錯誤: ${remote.version}`);
    }

    if (!remote.packageUrl) {
        throw new Error('packageUrl 不可為空');
    }

    const url = new URL(remote.packageUrl);

    if (url.protocol !== 'https:' && url.protocol !== 'http:') {
        throw new Error('packageUrl 只允許 HTTP(S)');
    }

    const pathname = url.pathname.replace(/\/+$/, '');
    const urlBundleName = pathname.slice(pathname.lastIndexOf('/') + 1);

    if (urlBundleName !== bundleName) {
        throw new Error(`packageUrl 必須以 /${bundleName} 結尾，目前是 ${remote.packageUrl}`);
    }
}

function normalizeUrl(url: string): string {
    return url.replace(/\/+$/, '');
}
